local module = {}

function module.tile() return gaps.tile end
function module.paper() return gaps.paper end

-- A continent's gap tiles: { col, row } each.
function module.tilesOf(continent)
	local list, flat = {}, gaps[continent] or {}
	for k = 1, #flat - 2, 3 do list[#list + 1] = { col = flat[k], row = flat[k + 1] } end
	return list
end

-- Blizzard's classic maps: { name, left, top, right, bottom, files } (0 to 1 on the world; a file 0 is none).
function module.classic()
	local list = {}
	for _, x in ipairs(gaps.art or {}) do
		local r = x[3]
		list[#list + 1] = { name = x[1], left = r[1], top = r[3], right = r[2], bottom = r[4], files = x[4] }
	end
	return list
end

-- The fills painted by hand: { name, left, top, right, bottom, width, height, columns, tiles }.
function module.fills()
	local list = {}
	for _, x in ipairs(fills) do
		local r = x[2]
		list[#list + 1] = { name = x[1], left = r[1], top = r[2], right = r[3], bottom = r[4], width = x[3], height = x[4], columns = x[5], tiles = x[6] }
	end
	return list
end

LunaType.addon(name)["gaps"] = module
